const BASE = window.location.origin;
const WORKSPACE_ID = constants.WS;
const UTIL_TABLE = constants.UTIL_TABLE;

let access = variables.access;
if (!access || !access.is) {
  try {
    const src = constants.ACCESS_RESOLVER_CODE;
    if (src) {
      const fn = new Function('globals', 'constants', 'return (' + src + ')(globals, constants);');
      access = fn(globals, constants);
      await actions.setVariable('access', access);
    } else {
      access = {};
    }
  } catch (e) {
    console.error('renderTilesV2: inline access resolve failed', e);
    access = {};
  }
}

const accessDomains = Array.isArray(access.domains) ? access.domains : [];
const hasAllDomains = !!access.has_all_domains;
const isMaker = !!(access.is && access.is.maker);
const isChecker = !!(access.is && access.is.checker);
const isAdmin = !!(access.is && access.is.admin);
const isBuilder = !!(access.is && access.is.builder);

let rows = [];
try {
  const r = await fetch(`${BASE}/api/tooljet-db/proxy/${UTIL_TABLE}?type=eq.domestic&order=created_at.desc`, {
    credentials: 'include',
    headers: { 'Tj-Workspace-Id': WORKSPACE_ID }
  });
  const text = await r.text();
  rows = text ? JSON.parse(text) : [];
  if (!Array.isArray(rows)) rows = [];
} catch (e) {
  rows = [];
}

if (rows.length === 0) {
  return { html: '<div style="margin:0 24px 22px;padding:48px 20px;text-align:center;color:#6b7486;font-size:13px;border:1px dashed #e7ebf2;border-radius:20px;background:rgba(255,255,255,0.5)">No apps yet. Click \"+ Create new App\" to get started.</div>', rows: [] };
}

function initialsOf(name) {
  if (!name) return '?';
  const parts = String(name).split(/\s+/).filter(Boolean);
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0].charAt(0) + parts[1].charAt(0)).toUpperCase();
}

const cards = rows.map(function (row) {
  const name = row.name || 'Untitled';
  const domainKey = name.replace(/\s+/g, '_');
  const hasDomain = hasAllDomains || accessDomains.includes(domainKey);
  const hasRole = isMaker || isChecker;
  const hasAccess = isAdmin || isBuilder || (hasDomain && hasRole);
  const clickable = hasAccess && !!row.tj_app_id;

  const isAdminOrBuilder = isAdmin || isBuilder;
  const url = clickable
    ? (isAdminOrBuilder
        ? `${BASE}/${WORKSPACE_ID}/apps/${row.tj_app_id}`
        : `${BASE}/applications/${row.tj_app_id}`)
    : '#';
  const initials = initialsOf(name);
  const sub = row.api_base_url ? String(row.api_base_url).replace(/^https?:\/\//, '').replace(/\/$/, '') : (row.type || '');

  const badge = !hasAccess ? '<span style="display:inline-block;margin-top:6px;padding:2px 8px;border-radius:6px;background:rgba(107,116,134,0.08);color:#6b7486;font-size:10px;font-weight:600;letter-spacing:0.03em">No access</span>' : '';

  return `\n  <a href="${url}" target="_top" style="text-decoration:none;display:block;color:inherit;pointer-events:${clickable ? 'auto' : 'none'}" onclick="${clickable ? '' : 'return false'}">\n    <article style="min-height:112px;padding:16px 18px;border-radius:20px;border:1px solid #e7ebf2;background:linear-gradient(160deg,rgba(234,239,252,0.72) 0%,rgba(248,249,254,0.96) 100%);display:flex;flex-direction:column;justify-content:space-between;font-family:inherit;color:#2a3140;cursor:${clickable ? 'pointer' : 'default'};opacity:${hasAccess ? 1 : 0.45}">\n      <div style=\"display:flex;align-items:flex-start;justify-content:space-between;gap:12px\">\n        <h4 style=\"margin:0;font-size:15px;line-height:1.2;letter-spacing:-0.02em;font-weight:700;overflow:hidden;text-overflow:ellipsis\">${name}</h4>\n        <span style=\"display:grid;place-items:center;width:32px;height:32px;border-radius:10px;flex-shrink:0;background:rgba(28,71,204,0.07);border:1px solid rgba(28,71,204,0.1);color:#1c47cc;font-size:11px;font-weight:800;letter-spacing:0.04em\">${initials}</span>\n      </div>\n      <div style=\"color:#6b7486;font-size:12px;line-height:1.4;overflow:hidden;text-overflow:ellipsis;white-space:nowrap\">${sub}${badge}</div>\n    </article>\n  </a>`;
}).join('');

const html = `<div class="coc-app-card-wrap" style="display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:0 24px 22px;font-family:inherit">${cards}</div>`;
return { html, rows };
